// Positive configurations of flags in ℝP² from Fock–Goncharov coordinates on the once-punctured
// torus, after Fock and Goncharov, "Moduli spaces of convex projective structures on surfaces"
// (Adv. Math., 2007).
//
// A flag is a point p (column 3-vector) on a line l (row 3-vector, l·p = 0). The torus is cut by
// three edges e1, e2, e3 into two ideal triangles T1, T2. Its universal cover is the Farey
// tessellation of the disk, with vertices ℚ ∪ {∞}: the torus group is the commutator subgroup of
// PSL(2,ℤ), generated by a(x) = (x+1)/(x+2) and b(x) = (x−1)/(2−x), with fundamental domain the
// quadrilateral −1, 0, 1, ∞, cut by the edge 0∞ into T1 = (∞, −1, 0) and T2 = (0, 1, ∞).
// The coordinates are, for each triangle, the triple ratio of its three flags, and for each edge two
// cross-ratios, one at each end, of the four lines through that end: its own line, the edge and the
// two lines to the far corners of the triangles on either side. All of them positive is exactly the
// condition that the flags are in convex position, that the group is discrete and faithful, and that
// it divides a properly convex domain Ω whose boundary is the closure of the points of the flags.
//
// Every Farey edge (L, R) splits off the triangle (L, M, R) with M the mediant, and the flag at M
// follows from the flags at L, R and the far corner O of the triangle on the other side (across()).
// So the whole configuration grows from three flags, without any group element.

export const dot = (l, p) => l[0] * p[0] + l[1] * p[1] + l[2] * p[2];
export const cross = (u, v) => [u[1] * v[2] - u[2] * v[1], u[2] * v[0] - u[0] * v[2], u[0] * v[1] - u[1] * v[0]];
const det = (u, v, w) => dot(cross(u, v), w);
const comb = (a, u, b, v) => [a * u[0] + b * v[0], a * u[1] + b * v[1], a * u[2] + b * v[2]];
const unit = v => { const n = Math.hypot(v[0], v[1], v[2]); return [v[0] / n, v[1] / n, v[2] / n]; };

// triple ratio of three flags, invariant under cyclic permutation; 1 for three points of a conic
// with their tangents
export function tripleRatio([p1, l1], [p2, l2], [p3, l3]) {
  return dot(l1, p2) * dot(l2, p3) * dot(l3, p1) / (dot(l1, p3) * dot(l2, p1) * dot(l3, p2));
}

// the cross-ratio at the end p1 of the edge 13, where (1, 2, 3) runs counterclockwise and 4 lies on
// the other side: of the lines l1, p1p2, p1p3, p1p4. It is 1 for the points 0, 1, ∞, −1 of a conic
export function edgeRatio([p1, l1], [p2], [p3], [p4]) {
  const b = (u, v) => det(u, v, p1);
  const L12 = cross(p1, p2), L13 = cross(p1, p3), L14 = cross(p1, p4);
  return -b(l1, L12) * b(L13, L14) / (b(l1, L14) * b(L13, L12));
}

// the line through p (the middle flag j of the counterclockwise triple i, j, k) that makes the
// triple ratio X
function lineFor(Fi, p, Fk, X) {
  const [pi, li] = Fi, [pk, lk] = Fk;
  const Jji = cross(p, pi), Jjk = cross(p, pk);
  const g = X * dot(li, pk) * dot(Jjk, pi) * dot(lk, p) / (dot(li, p) * dot(Jji, pk) * dot(lk, pi));
  return unit(comb(g, Jji, 1, Jjk));
}

// the flag F4 across the edge 13 from F2, for (1, 2, 3) counterclockwise: z1, z3 are the edge's
// cross-ratios at its ends, Y the triple ratio of the new triangle (3, 4, 1)
export function across(F1, F2, F3, z1, z3, Y) {
  const [p1, l1] = F1, [p2] = F2, [p3, l3] = F3;
  const L12 = cross(p1, p2), L13 = cross(p1, p3), L32 = cross(p3, p2);
  const b1 = (u, v) => det(u, v, p1), b3 = (u, v) => det(u, v, p3);
  const L14 = comb(z1 * b1(L13, L12) / b1(l1, L12), l1, 1, L13);
  const L34 = comb(b3(L13, L32) / (z3 * b3(l3, L32)), l3, 1, L13);
  const p4 = unit(cross(L14, L34));
  return [p4, lineFor(F3, p4, F1, Y)];
}

// The coordinates, as an object { t1, t2, e1, e2, e3 }: t1, t2 the triple ratios of T1, T2, and each
// edge a pair [tail, head], ordered so that T2 lies on the right of the walk from tail to head, which
// is 0 → ∞ for e1, 1 → 0 for e2 and ∞ → 1 for e3.
//
// An interval of the boundary circle, a Farey edge (L, R) with L before R counterclockwise, is
// { L, R, O, k, type }: the flags at its ends and at the far corner O of the triangle beyond it,
// the class k ∈ {0, 1, 2} of the edge and the type (0 for T1, 1 for T2) of the triangle (L, M, R)
// below it. That triangle's edges LM and MR have classes k + 1 and k + 2, and the triangles below
// them have the other type.

const EDGES = ['e1', 'e2', 'e3'];

export function mediant(c, { L, R, O, k, type }) {
  const [tail, head] = c[EDGES[k]];
  // R is the tail when the new triangle is T1, as then T2 lies beyond the edge
  const zR = type === 0 ? tail : head, zL = type === 0 ? head : tail;
  return across(R, O, L, zR, zL, type === 0 ? c.t1 : c.t2);
}

export function split(c, iv, M = mediant(c, iv)) {
  const t = 1 - iv.type;
  return [
    { L: iv.L, R: M, O: iv.R, k: (iv.k + 1) % 3, type: t },
    { L: M, R: iv.R, O: iv.L, k: (iv.k + 2) % 3, type: t },
  ];
}

// The flags at 0, 1, ∞ and −1 (T2's ends at 0, 1, ∞ on the conic xz = y², the line at 1 turned to
// give the triple ratio t2), and the four intervals of the circle between them, counterclockwise from 0.
export function seed(c) {
  const conic = t => t === Infinity ? [[0, 0, 1], [1, 0, 0]] : [unit([1, t, t * t]), unit([t * t, -2 * t, 1])];
  const F0 = conic(0), Finf = conic(Infinity);
  const p1 = conic(1)[0];
  const F1 = [p1, lineFor(F0, p1, Finf, c.t2)];
  const [e1t, e1h] = c.e1;
  // T1 = (∞, −1, 0) lies beyond e1 from 1: across the edge from F1, at R = 0 (e1's tail) and L = ∞
  const Fm1 = across(F0, F1, Finf, e1t, e1h, c.t1);
  const flags = { 0: F0, 1: F1, inf: Finf, '-1': Fm1 };
  const intervals = [
    { L: F0, R: F1, O: Finf, k: 1, type: 0 },
    { L: F1, R: Finf, O: F0, k: 2, type: 0 },
    { L: Finf, R: Fm1, O: F0, k: 1, type: 1 },
    { L: Fm1, R: F0, O: Finf, k: 2, type: 1 },
  ];
  return { flags, intervals };
}

// ---------- the group ----------

const m3 = (A, B) => A.map(r => [0, 1, 2].map(j => r[0] * B[0][j] + r[1] * B[1][j] + r[2] * B[2][j]));
export const mmul = m3;
export const apply = (M, p) => M.map(r => dot(r, p));

function inv3(M) {
  const [a, b, c] = M;
  const C = [cross(b, c), cross(c, a), cross(a, b)]; // rows of the adjugate's transpose
  const d = dot(a, C[0]);
  return [0, 1, 2].map(i => [0, 1, 2].map(j => C[j][i] / d));
}
export const inverse = inv3;

// the projective map taking three flags to three others with the same triple ratio,
// normalised to determinant 1
function frame([[p1, l1], [p2, l2], [p3]]) {
  const q = cross(l1, l2);
  const P = [0, 1, 2].map(i => [p1[i], p2[i], p3[i]]);
  const w = apply(inv3(P), q);
  return P.map(r => r.map((v, j) => v * w[j]));
}
export function flagMap(src, dst) {
  const M = m3(frame(dst), inv3(frame(src)));
  const d = Math.cbrt(dot(M[0], cross(M[1], M[2])));
  return M.map(r => r.map(v => v / d));
}

// a and b as matrices: a takes (−1, ∞, −2) to (0, 1, ∞), b takes (1, ∞, 2) to (0, −1, ∞)
export function generators(c) {
  const { flags, intervals } = seed(c);
  const Fm2 = mediant(c, intervals[2]), F2 = mediant(c, intervals[1]);
  const a = flagMap([flags['-1'], flags.inf, Fm2], [flags[0], flags[1], flags.inf]);
  const b = flagMap([flags[1], flags.inf, F2], [flags[0], flags['-1'], flags.inf]);
  return { a, b, A: inv3(a), B: inv3(b) };
}

// the triple ratios and edge ratios of the flags in a seed, read back (for tests)
export function readBack(c) {
  const { flags: f, intervals } = seed(c);
  const Fm2 = mediant(c, intervals[2]), F2 = mediant(c, intervals[1]), Fh = mediant(c, intervals[0]);
  return {
    t1: tripleRatio(f.inf, f['-1'], f[0]),
    t2: tripleRatio(f[0], f[1], f.inf),
    e1: [edgeRatio(f[0], f[1], f.inf, f['-1']), edgeRatio(f.inf, f['-1'], f[0], f[1])],
    // e2 as the edge (∞, −1)... read on its copy 1 → 0 with T2 = (0, 1, ∞) to its right
    e2: [edgeRatio(f[1], f.inf, f[0], Fh), edgeRatio(f[0], Fh, f[1], f.inf)],
    e3: [edgeRatio(f.inf, f[0], f[1], F2), edgeRatio(f[1], F2, f.inf, f[0])],
  };
}
